\emph{(Spectral expansion of $L^2(\Gamma \backslash G,\chi)$)}.
  Let $q\in {\mathbb Z}_{>0}$, $\chi$ be a Dirichlet character to the modulus $q$ of parity $\kappa \in \{0,1\}$, and let $\Gamma=\Gamma_0(q)$.  There exists a countable set  $\mathcal{B}(q,\chi) $ and for $V \in \mathcal{B}(q,\chi),\ell\in {\mathbb Z}, \ell \equiv \kappa \,\,(\mathrm{mod}\,{2})$, complex numbers $\nu_V$, and smooth functions $\varphi^{(\ell)}_V \in L^2(\Gamma \backslash G,\chi)$ of right-type $\ell$ with \begin{align}
        \Omega \varphi^{(\ell)}_V=\bigg(\frac{1}{4}-\nu_V^2\bigg)\varphi^{(\ell)}_V
    \end{align} 
    such that the following holds. For any smooth and bounded $f\in L^2(\Gamma \backslash G,\chi)$ with $\Omega f$ bounded we have
    \begin{align*}
        f(g)= &\mathbf{1}_{\chi \,\mathrm{principal}}\frac{1}{|\Gamma \backslash G|} \langle f ,1 \rangle_{\Gamma \backslash G} +\sum_{V \in \mathcal{B}(q,\chi)} \sum_{\ell\equiv \kappa \,\,(\mathrm{mod}\,{2})}\langle f ,\varphi_V^{(\ell)} \rangle_{\Gamma \backslash G}  \varphi_V^{(\ell)}(g)\\
        &+\sum_{\mathfrak{c}\in \mathfrak{C}(q,\chi)} \sum_{\ell\equiv \kappa \,\,(\mathrm{mod}\,{2})} \frac{1}{4 \pi i} \int_{(0)} \langle f, E^{(\ell)}_{\mathfrak{c}}(*,\nu) \rangle_{\Gamma \backslash G}  E^{(\ell)}_{\mathfrak{c}}(g,\nu) \mathrm d \nu.
    \end{align*}

Let $k:G \to {\mathbb C}$ be smooth and compactly supported. Define
    \begin{align*}
        K^{(\ell)}(\tau_1,\tau_2) := \sum_{\gamma \in \Gamma} \overline{\chi}(\gamma)k_{\ell,\ell}(\tau_2^{-1} \gamma \tau_1).
    \end{align*}
   Then for $\ell \equiv \kappa \,\,(\mathrm{mod}\,{2})$
    \begin{align*}
        K^{(\ell)}(\tau_1,\tau_2) = & \frac{\mathbf{1}_{\chi \,\mathrm{principal}} \mathbf{1}_{\ell=0}}{|\Gamma \backslash G|} \int_G k(g) \mathrm d g  \\
      &+  \sum_{V\in \mathcal{B}(q,\chi)}
        \Phi_{\ell,\ell}(k;\nu_V) \varphi_V^{(\ell)}(\tau_1) \overline{\varphi_V^{(\ell)}(\tau_2)} \\
&+\sum_{\mathfrak{c}\in \mathfrak{C}(q,\chi)} \frac{1}{4 \pi i}  \int_{(0)}  \Phi_{\ell,\ell}(k;\nu)E^{(\ell)}_{\mathfrak{c}}(\tau_1,\nu) \overline{E^{(\ell)}_{\mathfrak{c}}(\tau_2,\nu)} \mathrm d \nu,
    \end{align*}
    where 
    \begin{align} 
\Phi_{\ell,\ell}(k;\nu) :=& \int_G  k_{\ell,\ell}(h) \overline{\phi_{\ell}(h,\nu)} \mathrm d h .
    \end{align}

Let $K,L \geq 1.$ There exists a function $k:G \to [0,1]$ satisfying
 \begin{align*}
     k(\smqty(a& b \\ c & d)) \leq \mathbf{1}_{|a|+|b|+|c|+|d| \leq 6}
 \end{align*}
 such that the following holds.  Let $T \subseteq G$ be a finite set and let $\alpha:T \to {\mathbb C}$ be a function. Then 
    \begin{align*}
     \sum_{\substack{V \in \mathcal{B}(q,\chi) \\  |\nu_V| \leq K }} \sum_{\substack{|\ell| \leq L  \\ \ell \equiv \kappa \,\,(\mathrm{mod}\,{2})}} \bigg| \sum_{\tau \in T }\alpha(\tau) \varphi_V^{(\ell)} (\tau)\bigg|^2& + \sum_{\mathfrak{c} \in \mathfrak{C}(q,\chi)} \sum_{\substack{|\ell| \leq L  \\ \ell \equiv \kappa \,\,(\mathrm{mod}\,{2})}} \int_{-iK}^{iK} \bigg| \sum_{\tau \in T }\alpha(\tau) E_{\mathfrak{c},\ell}(\tau,\nu)\bigg|^2 |\mathrm d \nu| \\
     & \ll K^2 L \sum_{\tau_1,\tau_2 \in T} \alpha(\tau_1) \overline{\alpha(\tau_2)} \sum_{\gamma \in \Gamma} \overline{\chi}(\gamma) k(\tau_2^{-1} \gamma \tau_1).
    \end{align*}

Let $\delta \in (0,1)$ and $X,Y > 0$, $\kappa \in \{0,1\}$. Let $a_{V,\ell},b_{\mathfrak{c},\nu,\ell,}:{\mathbb Z}_{>0} \to {\mathbb C}$ and let $F:G \to {\mathbb C}$,  $F(g)=F(\mathrm{n}[x] \mathrm{a}[y] \mathrm{k}[\theta])$, be  $(2J+1)$ times differentiable in all three variables, supported on $(x,y) \in [-X,X]\times [Y,2Y]$, satisfying for all $J_1,J_2,J_3 \geq 0$ with $J_1+J_2+J_3 \leq 2J+1$
\begin{align}
        \partial_x^{J_1} \partial_y^{J_2}  \partial_\theta^{J_3} F \ll (\delta X)^{-J_1} (\delta Y)^{-J_2} (\delta)^{-J_3}.
    \end{align}
    Define the decay function
    \begin{align} 
        D_J(t,\nu,\ell) :=\min_{J_0\in \{0,1,\dots,J\}} \frac{ (1+\log t)^2 (1+Y/X)^{2J_0} }{\delta^{2}(1+|\delta \nu| + |\delta t X| + |\delta\ell|)^{2J_0-1}  } 
    \end{align}
    Then for $\sigma \in \{\pm\}$ we have for any $J\geq0$   \begin{align}
    \begin{split}
 \sum_{\substack{V \in \mathcal{B}(q,\chi) \\ \operatorname{Re}(\nu_V) < 1/2}}& \sum_{\ell \equiv \kappa \,\,(\mathrm{mod}\,{2}) }  \sum_{n > 0} 
 \langle F, \mathcal{A}^{\sigma} \phi_\ell(\mathrm{a}[n] \cdot,\nu_V) \rangle_{G} \, \frac{a_{V,\ell}(n)}{\sqrt{n}} \\
 \ll & \max_{t > 0} \frac{X}{Y^{1/2}}\sum_{\substack{V\in \mathcal{B}(q,\chi) \\ \operatorname{Re}(\nu_V) < 1/2}} \sum_{\ell \equiv \kappa \,\,(\mathrm{mod}\,{2}) }(  Yt  )^{- \operatorname{Re}(\nu_V)}    D_J(t,\nu_V,\ell) 
 \bigg| \sum_{0< n \leq t}  a_{V,\ell}(n)  \bigg|,
    \end{split} 
    \end{align}
    \begin{align}

        \begin{split}
        \sum_{\substack{V \in \mathcal{B}(q,\chi) \\ \nu_V = (k-1)/2}} \sum_{\substack{\ell \equiv \kappa \,\,(\mathrm{mod}\,{2})\\ \sigma \ell \geq k}}  &\left|\pi^{-2\nu_V}\frac{\Gamma(|\ell|/2+\nu_V+1/2)}{\Gamma(|\ell|/2-\nu_V+1/2)} \right|^{1/2} \sum_{n > 0} 
 \langle F, \mathcal{A}^{\sigma} \phi_\ell(\mathrm{a}[n] \cdot,\nu_V) \rangle_{G} \, \frac{a_{V,\ell}(n)}{\sqrt{n}} \\
 & \ll \max_{t > 0}   \frac{X}{Y^{1/2}}  \sum_{\substack{V \in \mathcal{B}(q,\chi)\\ \nu_V = (k-1)/2}}  \sum_{\substack{\ell \equiv \kappa \,\,(\mathrm{mod}\,{2})\\ \sigma \ell \geq k}} D_J(t,\nu_V,\ell)\bigg| \sum_{0 < n \leq t}  a_{V,\ell}(n)  \bigg|,
        \end{split}
    \end{align}
and
 \begin{align}
 \begin{split}
       \sum_{\mathfrak c \in \mathfrak{C}(q,\chi)} &\sum_{\ell \equiv \kappa \,\,(\mathrm{mod}\,{2})} \int_{(0)}  \sum_{n > 0} 
 \langle F, \mathcal{A}^{\sigma} \phi_\ell(\mathrm{a}[n] \cdot,\nu) \rangle_{G} \, \frac{b_{\mathfrak c,\nu,\ell}(n)}{\sqrt{n}} \mathrm d \nu  \\
 &\ll \max_{t > 0}  \frac{X}{Y^{1/2}} \sum_{\mathfrak c \in \mathfrak{C}(q,\chi)}\int_{(0)} \sum_{\ell \equiv \kappa \,\,(\mathrm{mod}\,{2})} D_J(t,\nu,\ell) \bigg| \sum_{0< n \leq t}  b_{\mathfrak c,\nu,\ell}(n) \bigg| |\mathrm d \nu|.
 \end{split}
    \end{align}

Let $K\ge 1$, $N\ge 1/2$, $\varepsilon>0$ be real, and $a_n$ be a sequence of complex numbers supported on $n\sim N$. Each of the expressions
    \begin{align}
    &\sum_{\substack{ V \in \mathcal{B}(q,\chi) \\|\nu_V|\leq K}} \left|\sum_n a_n \varrho_V(n) \right|^2\\
       & \sum_{c\in \mathfrak{C}(q,\chi)} \int_{-iK}^{iK} \left|\sum_n a_n \varrho_{\mathfrak{c},\nu}(n) \right|^2 |\mathrm d \nu|
    \end{align}
    is bounded by
    \begin{align*}
        \ll_\varepsilon (K^2+N^{1+\varepsilon}\mathrm{cond}(\chi)^{1/2}/q) \|  a_n \|_2^2.
    \end{align*}

Let $a_n$ be a sequence of complex numbers supported on $n\sim N$.    We have
    \begin{align*}
        \sum_{\substack{V\in \mathcal{B}(q,\chi) \\ \operatorname{Re}(\nu_V) \in (0,1/2)}} X^{2 \nu_V} \left|\sum_{n} a_n   \varrho_V(n) \right|^2\ll \left(1+\bigg(\frac{NX}{q}\bigg)^{2\theta_q} \right)\left(1+ \mathrm{cond}(\chi)^{1/2}\bigg(\frac{N^{1+\varepsilon}}{q}\bigg)^{1-2\theta_q} \right)\|  a_n\|_2^2
    \end{align*}
    and for any $N<N_1\leq 2N$
    \begin{align*}
       \sum_{\substack{q\sim Q \\ \mathrm{cond}(\chi) | q}}    \sum_{\substack{V\in \mathcal{B}(q,\chi) \\ \operatorname{Re}(\nu_V) \in (0,1/2)}} X^{2 \nu_V} \left|\sum_{N<n\leq N_1}  \varrho_V(n) \right|^2 \ll_\varepsilon (QN)^\varepsilon  \bigg(\frac{Q} {\mathrm{cond}(\chi)}  + N +  X^{2\theta} N^{2\theta} Q^{1-4\theta}\bigg) N
    \end{align*}

Let $\Gamma=\Gamma_2(q_1,q_2)$ for some $q_1,q_2 \geq 1$, $q=q_1q_2$, and let $T \subseteq G= \operatorname{SL}_2({\mathbb R})$ be a finite set. Let $\alpha: T \to {\mathbb C}$ and $\beta:{\mathbb Z}_{> 0} \to {\mathbb C}$. Let $\chi$ be a Dirichlet character to the modulus $q$ and denote the corresponding group character on $\Gamma_2(q_1,q_2)$ by $\overline{\chi}(\smqty(a & b \\ c & d)) :=  \overline{\chi}(d)$. 

Let $A,C,D >0$, $\delta \in (0,1)$ with $AD > \delta$. Let $J \geq 3$, $f \in C_\delta^{2J+1}(A,C,D)$ and let $F: G \to {\mathbb C}$ denote  $F(\smqty(a&b \\ c& d))=f(a,c,d)$.
Denote 
\begin{align*}
    P_{f}(\tau) := \sum_{\gamma \in \Gamma} \overline{\chi}(\gamma) F(\gamma \tau), 
\end{align*}
\begin{align*}
   S_{f,\alpha,\beta,\chi}(\Gamma,T):= \sum_{\tau \in T}  \sum_{\gcd(h,q)=1} \alpha(\tau) \beta_h \mathcal{T}_h P_{f}(\tau), 
\end{align*}
and
\begin{align}
     M_{f,\alpha,\beta,\chi}(\Gamma,T)  &:= \mathbf{1}_{\chi \, \mathrm{principal}}\bigg(\sum_{\gcd(h,q)=1}\frac{\beta_h \sigma_1(h)}{\sqrt{h}}\bigg)\bigg(\sum_{\tau \in T} \alpha(\tau) \bigg) \frac{1}{|\Gamma \backslash G|}  \int_{G} F(g) \mathrm d g.
\end{align}
Let 
\begin{align*}
   Z  :=\max\{ A^{\pm 1}, C^{\pm 1}, D^{\pm 1}, \delta^{-1}\} .
\end{align*}
Define the decay function
\begin{align*}
    E_J(t,\nu):= \frac{1}{ (1+ |t|+|\nu|)^{2J-1}}.
\end{align*} 
Then for  $L:=C/D$, $N:=q_1\frac{CD}{AD+1},$ and for any $\varepsilon > 0$ we have
\begin{align}
   | S_{f,\alpha,\beta,\chi}(\Gamma,T)  -   M_{f,\alpha,\beta,\chi}(\Gamma,T) |  \ll_{\varepsilon,J}  Z^\varepsilon \delta^{-O(1)}    (AD)^{1/2} \mathcal{K}_{\alpha,\chi}(\Gamma,T,L)^{1/2}\mathcal{R}_{\beta,\chi}(q_1,q_2,N)^{1/2},
\end{align}
where 
\begin{align*}
\mathcal{R}_{\beta,\chi}(q_1,q_2,N) := &\max_{t > 0}\frac{1}{N} \sum_{\substack{V \in\mathcal{B}(q,\chi)}} E_J(t/N,\nu_V)   \bigg( 1+\mathbf{1}_{\operatorname{Re}(\nu_V) < 1/2}\bigg(\frac{CD q_1 }{t}\bigg)^{2 \operatorname{Re}(\nu_V)} \bigg) |R_V(t,\beta)|^2 \\
&+ \max_{t > 0} \frac{1}{N} \sum_{\mathfrak c \in \mathfrak{C}(q,\chi)}\int_{(0)} E_J(t/N,\nu)  |R_{\mathfrak c,\nu }(t,\beta)|^2 |\mathrm d \nu| \, + \,\|\beta \|_1^2  N^{-1}
\end{align*}
with the two $R$ terms given by (7.3) and (7.4).
Further
\begin{align*}   \mathcal{K}_{\alpha,\chi}(\Gamma,T,L):=   \sum_{\tau_1, \tau_2 \in T} \alpha(\tau_1)  \overline{\alpha(\tau_2)}\sum_{\gamma \in \Gamma} \overline{\chi}(\gamma) k_L(\tau_2^{-1} \gamma\tau_1  )
\end{align*}
for some $k_L:G \to [0,1]$ which satisfies  
\begin{align*}
  k_L(\smqty(a& b \\ c & d)) \leq \mathbf{1}_{|a|+|b| L +|c|/L+|d| \leq 6}.
\end{align*}

Let $\mathcal{M} \subseteq \operatorname{SL}_2({\mathbb R})$,\, $q_1,q_2\in {\mathbb Z}_{>0}$ and denote $\Gamma = \Gamma_2(q_1,q_2)$. Let $\mathrm d g$ denote integration with respect to the Haar measure of the group $\operatorname{SL}_2({\mathbb R})$. Assume that $\mathcal{M}$ is left 
$\Gamma$-invariant with finitely many orbits $\Gamma \backslash \mathcal{M}$ and let $\alpha \in \mathcal{A}(\Gamma \backslash \mathcal{M})$.  Let $A,C,D,\delta > 0$  with $AD > \delta$ and let $f \in C^{7}_\delta (A,C,D)$. Denote $F:\operatorname{SL}_2({\mathbb R}) \to {\mathbb C}, \, F(\smqty(a & b \\ c& d)):= f(a,c,d)$. Then for any $\varepsilon > 0$ we have
\begin{align*}
   \bigg|  \sum_{g \in \mathcal{M}}  \alpha(g) F(g)  -  \frac{1}{|\Gamma \backslash \operatorname{SL}_2({\mathbb R}) |} \sum_{\tau \in \Gamma \backslash \mathcal{M}} \alpha(\tau)  \int_{\operatorname{SL}_2({\mathbb R})} F(g) \, \mathrm d g \bigg|  \ll_\varepsilon \delta^{-O(1)} Z^\varepsilon  \sqrt{ AD \, \mathcal{K} \, \mathcal{R}},
\end{align*}
where $Z = \max\{A^{\pm 1},C^{\pm 1},D^{\pm 1}\}$,
\begin{align*}
\mathcal{K}& = \sum_{\substack{g =\smqty(a & b \\mathfrak c & d) \in \mathcal{M}^{-1} \mathcal{M} \\  |a|+|b|C/D+|c|D/C+|d| \,\leq 6}}\Bigl|\sum_{ \substack{\tau\in \Gamma \backslash \mathcal{M} 
 \\ \tau g \in \mathcal{M}}} \alpha(\tau) \overline{\alpha(\tau g)} \Bigr|, \quad \quad\text{and} \\
\mathcal{R}& =    \left(1+ (AD)^{2\theta}\bigg( \frac{ C}{ A q_2}\bigg)^{2\theta} \right)\left(1+\bigg(\frac{C}{A q_2}\bigg)^{1-2\theta} \right) + \frac{A}{Cq_1}, \quad \theta=7/64.
\end{align*}

\emph{(Determinant equation twisted by an automorphic function).} 
    Let $q_1,q_2 \in {\mathbb Z}_{> 0}$. For non-zero integers $h,k$ denote
\begin{align*}
    \operatorname{M}_{2,h,k}({\mathbb Z}) := \bigg\{ \mqty(a &b \\ c &d) \in \operatorname{M}_{2,hk}({\mathbb Z}): \,\gcd (a,c,k)=\gcd(b,d,k)=1 \bigg\},
\end{align*}
Denote
 \begin{align*}
    q=q_1q_2, \quad \Gamma = \Gamma_2(q_1,q_2), \quad T := \Gamma \backslash \operatorname{SL}_2({\mathbb Z}), \quad T_{1,k}:= \operatorname{SL}_2({\mathbb Z}) \backslash \operatorname{M}_{2,1,k}({\mathbb Z}).
 \end{align*}   
Let $\chi$ be a Dirichlet character to a modulus dividing $q_1q_2$ and let $\xi_h$ be multiplicative complex coefficients. Let
\begin{align*}
    \alpha \in   \mathcal{A}(q_1,q_2,\chi,\xi).
\end{align*}
 Let $A,C,D,\delta,\eta >0$ with $AD > \delta$  and denote $Z := \max\{A^{\pm 1},C^{\pm 1},D^{\pm 1}, \delta^{-1}\}$. Let $H,K \geq  1$  and assume that $HK \leq (AD)^{1+\eta}$. Let 
 \begin{align*}
   f\in C^{7}_\delta \bigg( \frac{A}{\sqrt{HK}},\frac{C}{\sqrt{HK}},\frac{D}{\sqrt{HK}}\bigg).
 \end{align*} 
Let $\beta_h$ be supported on $|h| \in [H,2H]$ and $\gamma_k$ supported on $|k| \in [K,2K]$. Denote
 \begin{align}
       w(\sigma,\sigma_1,\sigma_2) =  \sum_{\tau \in T} \alpha(\tau \sigma \sigma_1)  \overline{\alpha(\tau \sigma_2)} 
   \end{align}
and assume that for some $\mathcal{K}_+ >0$ 
\begin{align} 
    \frac{1}{K} \sum_{k_1,k_2} |\gamma_{k_1} \gamma_{k_2}| \sum_{\substack{g=\smqty(a&b \\ c & d)  \in (k_1/k_2)^{1/2} \operatorname{SL}_2({\mathbb R}) \\ |a| + |b|C/D + |c|D/C + |d| \leq 10}} \bigg| \sum_{\substack{\sigma_j \in T_{1,k_j} \\ \sigma_2 g \sigma_1^{-1} =\sigma\in \operatorname{SL}_2({\mathbb Z}) }}  w(\sigma,\sigma_1,\sigma_2) \bigg| \ll Z^{O(\eta)} \mathcal{K}_+.
\end{align}
Then
\begin{align*}
   &\sum_{\substack{h,k \\ \gcd(h,kq)=1}} \beta_h \gamma_k \sum_{\substack{\smqty(a& b \\ c& d)\in \operatorname{M}_{2,h,k}({\mathbb Z})}}  \alpha(\smqty(a & b \\ c & d)) f\bigg(\frac{a}{ \sqrt{|hk|}},\frac{c}{ \sqrt{|hk|}},\frac{d}{ \sqrt{|hk|}}\bigg) \\
   =&   \frac{\mathbf{1}_{\chi \, \mathrm{principal}}}{ \zeta(2)
 q\, \prod_{p|q}(1+p^{-1}) }\sum_{\substack{h,k \\ \gcd(h,kq)=1}} \beta_h \xi_h \sigma_1(|h|) \gamma_k \sum_{\tau \in \Gamma \backslash \operatorname{M}_{2,1,k}({\mathbb Z})} \alpha(\tau)  \int_{{\mathbb R}^3} f(a,c,d) \frac{\mathrm d  a \mathrm d c \mathrm d d }{c}  \\
 &\hspace{80pt}+ O \left( Z^{O(\eta)} \delta^{-O(1)} (AD)^{1/2}  \|\beta \xi \|_2  \,  \mathcal{K}_+^{1/2} \left(\mathcal{R}_0 + \min_{j\in \{1,2\}}\mathcal{R}_j \right) \right),
\end{align*}
where 
\begin{align*}
    \mathcal{R}_0 &:= \frac{ \|\beta \xi \|_1  A^{1/2} }{\|\beta \xi \|_2  q_1^{1/2} C^{1/2}},  \\
    \mathcal{R}_1 &:=\frac{\|\beta  \xi \|_1}{\|\beta \xi \|_2} H^{\vartheta_q}  \left(1+\bigg(\frac{CD}{HK q_2 }\bigg)^{\theta_q} \right)\left(1+ \mathrm{cond}(\chi)^{1/4}\bigg(\frac{C}{A q_2}\bigg)^{1/2-\theta_q}\right) ,    \\
    \mathcal{R}_2 &:=\left(1+\bigg(\frac{ CD}{Kq_2}\bigg)^{\theta_q} \right)\left(1+ \mathrm{cond}(\chi)^{1/4}\bigg(\frac{H C}{A q_2 }\bigg)^{1/2-\theta_q}\right).
\end{align*}

Let
    \begin{align} 
U_h(r_1,r_2;q) &:=\prod_{p|q} \bigg( \mathbf{1}_{r_1\equiv 0 \,\,(\mathrm{mod}\,{p})} + \mathbf{1}_{r_2\equiv 0 \,\,(\mathrm{mod}\,{p})} + \mathbf{1}_{r_2\equiv -h \,\,(\mathrm{mod}\,{p})} + \mathbf{1}_{r_1 \equiv r_2 \,\,(\mathrm{mod}\,{p})} + p^{-1} \bigg) \\
    \mathcal{N}_h(t) &:= \sum_{r_1,r_2 \,\,(\mathrm{mod}\,{q})} |t(r_1) t(r_2)| U_h(r_1,r_2;q).
\end{align}
Then the asymptotic in Theorem 1.2 holds with the error term
\begin{align*}
    O\bigg( X^{1/2+O(\eta)} q^{1/2}\mathcal{N}_h(t)^{1/2}   (|h|^{\theta}+(X/q)^{\theta})  \bigg).
\end{align*}

Assume the requirements of Theorem 1.2 and let $r\in {\mathbb Z}$ with $\gcd(r,q)=1$. Then 
    \begin{align*}
        \sum_{n} G(n/X)d(n)d(n+h) e(n r/q) \ll \frac{d(q)}{q}X+X^{1/2+O(\eta)} q\bigg(|h|^{\theta}+(X/q)^{\theta}\bigg).
    \end{align*}

Assume the requirements of Theorem 1.2 and let $ \mathrm{MT}_G(X,r,h,q)$ given by (1.4). Then we have
    \begin{align*}
       \sum_{r(q)}  \left| \sum_{\substack{ n\equiv r \,\,(\mathrm{mod}\,{q})}}G(n/X)d(n) d(n+h)- \mathrm{MT}_G(X,r,h,q)\right| \ll X^{1/2+O(\eta)} q\bigg(|h|^{\theta}+(X/q)^{\theta}  \bigg).
    \end{align*}

Assume the requirements of Theorem 1.2, let $r\in {\mathbb Z}$ and $\mathrm{MT}_G(X,r,h,q)$ given by (1.4). Then we have
    \begin{align*}
        \sum_{\substack{ n\equiv r \,\,(\mathrm{mod}\,{q})}} G(n/X) d(n) d(n+h)=  \mathrm{MT}_G(X,r,h,q)+ O\bigg( X^{1/2+O(\eta)} q^{1/2}  (|h|^{\theta}+(X/q)^{\theta})  \bigg).
    \end{align*}

Assume that $q_1,q_2$ are square-free and let $\chi_1,\chi_2$ be different primitive Dirichlet characters to moduli $q_1,q_2$. Let $\eta>0$ and $\omega:(0,\infty)\to {\mathbb C}$ 
be a smooth compactly supported function with $\omega^{(j)} \ll_{j} T^{ j \eta }$ for all $j \geq 0$. Then for some quadratic polynomial $P_{\chi_1,\chi_2}$ we have 
    \begin{align*}
        \int_{\mathbb R} |L(1/2+it,\chi_1) |^2|L(1/2+it,\chi_2)|^2\omega(t/T) \mathrm d t= &\int_{\mathbb R} P_{\chi_1,\chi_2}(\log t) \omega(t/T) \mathrm d t  \\
        &+O\bigg(  \,(q_1q_2)^{3/4} \, T^{1/2+\theta+O(\eta)} \bigg).
    \end{align*}

Assume that $q$ is square-free and let $\chi$ be a primitive Dirichlet character to the modulus $q$. Let $\eta>0$ and $\omega:(0,\infty)\to {\mathbb C}$ 
be a smooth compactly supported function with $\omega^{(j)} \ll_{j} T^{ j \eta }$ for all $j \geq 0$. Then for some quartic polynomial $P_{\chi}$ we have
    \begin{align*}
        \int_{\mathbb R} |L(1/2+it,\chi) |^4\omega(t/T) \mathrm d t= &\int_{\mathbb R} P_{\chi}(\log t) \omega(t/T) \mathrm d t  +O\bigg(    \, q \, T^{1/2+\theta+ O(\eta)} \bigg).
    \end{align*}
